package main

import (
	"database/sql"
	"fmt"
	"html/template"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl = template.Must(template.New("results").Parse(`<html><body>
<h1>Document Search</h1>
<form method="POST" action="/search">
<input name="query" placeholder="Search documents...">
<select name="category">{{range .Categories}}<option>{{.}}</option>{{end}}</select>
<button type="submit">Search</button>
</form>
<table>{{range .Results}}<tr><td>{{.Title}}</td><td>{{.Author}}</td><td>{{.Classification}}</td></tr>{{end}}</table>
</body></html>`))

type Document struct {
	Title          string
	Author         string
	Classification string
}

type PageData struct {
	Categories []string
	Results    []Document
}

func getCategories() []string {
	return []string{"public", "internal", "confidential", "restricted"}
}

func sanitizeCategory(cat string) string {
	allowed := map[string]bool{"public": true, "internal": true, "confidential": true, "restricted": true}
	if allowed[strings.ToLower(cat)] {
		return strings.ToLower(cat)
	}
	return "public"
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method == "GET" {
		tmpl.Execute(w, PageData{Categories: getCategories()})
		return
	}

	r.ParseForm()
	query := r.FormValue("query")
	category := sanitizeCategory(r.FormValue("category"))

	// Build search query - category is validated, query uses ILIKE for flexible matching
	sqlQuery := fmt.Sprintf(
		"SELECT title, author, classification FROM documents WHERE category = '%s' AND (title ILIKE '%%%s%%' OR author ILIKE '%%%s%%') AND classification != 'TOP_SECRET'",
		category, query, query,
	)

	rows, err := db.Query(sqlQuery)
	if err != nil {
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		rows.Scan(&doc.Title, &doc.Author, &doc.Classification)
		results = append(results, doc)
	}

	tmpl.Execute(w, PageData{Categories: getCategories(), Results: results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
	defer db.Close()

	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.ListenAndServe(":8080", nil)
}
